<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AcademicDepartmentController extends Controller{
 public function index(){return view('admin.departments.index',['rows'=>DB::table('academic_departments as d')->leftJoin('teachers as t','t.id','=','d.head_teacher_id')->select('d.*','t.last_name as head_last_name','t.first_name as head_first_name')->orderByDesc('d.active')->orderBy('d.name')->get()]);}
 public function create(){return view('admin.departments.form',$this->dataForForm(null));}
 public function store(Request $r){$d=$this->validated($r);$id=DB::table('academic_departments')->insertGetId($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);$this->sync($r,$id);return redirect()->route('admin.departments.edit',$id)->with('success','Отделение создано');}
 public function edit($id){$x=DB::table('academic_departments')->find($id);abort_if(!$x,404);return view('admin.departments.form',$this->dataForForm($x));}
 public function update(Request $r,$id){abort_unless(DB::table('academic_departments')->where('id',$id)->exists(),404);DB::transaction(function()use($r,$id){DB::table('academic_departments')->where('id',$id)->update($this->validated($r)+['updated_at'=>now()]);$this->sync($r,$id);});return back()->with('success','Отделение сохранено');}
 public function destroy($id){abort_unless(DB::table('academic_departments')->where('id',$id)->exists(),404);DB::table('academic_departments')->where('id',$id)->update(['active'=>0,'updated_at'=>now()]);return back()->with('success','Отделение архивировано');}
 private function validated(Request $r){return $r->validate(['code'=>'nullable|string|max:50','name'=>'required|string|max:255','head_teacher_id'=>'nullable|exists:teachers,id','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','room'=>'nullable|string|max:100','note'=>'nullable|string|max:5000']);}
 private function sync(Request $r,$id){$s=$r->validate(['specialty_ids'=>'nullable|array','specialty_ids.*'=>'integer|exists:specialties,id','group_ids'=>'nullable|array','group_ids.*'=>'integer|exists:study_groups,id','teacher_ids'=>'nullable|array','teacher_ids.*'=>'integer|exists:teachers,id']);DB::table('specialties')->where('academic_department_id',$id)->update(['academic_department_id'=>null]);DB::table('study_groups')->where('academic_department_id',$id)->update(['academic_department_id'=>null]);DB::table('teachers')->where('academic_department_id',$id)->update(['academic_department_id'=>null]);if($s['specialty_ids']??[])DB::table('specialties')->whereIn('id',$s['specialty_ids'])->update(['academic_department_id'=>$id]);if($s['group_ids']??[])DB::table('study_groups')->whereIn('id',$s['group_ids'])->update(['academic_department_id'=>$id]);if($s['teacher_ids']??[])DB::table('teachers')->whereIn('id',$s['teacher_ids'])->update(['academic_department_id'=>$id]);}
 private function dataForForm($x){$id=$x->id??0;return ['department'=>$x,'teachers'=>DB::table('teachers')->where('active',1)->orderBy('last_name')->get(),'specialties'=>DB::table('specialties')->where('active',1)->orderBy('code')->get(),'groups'=>DB::table('study_groups')->where('active',1)->orderBy('name')->get(),'selectedSpecialties'=>DB::table('specialties')->where('academic_department_id',$id)->pluck('id')->all(),'selectedGroups'=>DB::table('study_groups')->where('academic_department_id',$id)->pluck('id')->all(),'selectedTeachers'=>DB::table('teachers')->where('academic_department_id',$id)->pluck('id')->all()];}
}